import yaml

ROOT = Path(__file__).resolve().parents[2]
d=yaml.safe_load(open(ROOT / 'docs/engineering/openapi/openapi.yaml'))
ops={}
for p,v in d['paths'].items():
    for m,o in v.items():
        if m in('get','post','put','patch','delete'): ops[o['operationId']]=(m.upper(),p,o['tags'][0])

