import re
# verify every test id mentioned (expanding ranges) exists
def expand(tok):
    tok=tok.strip()
    m=re.match(r'([A-Z0-9]+)-(\d+)…[A-Z0-9]+-(\d+)',tok)
    if m: return [f"{m.group(1)}-{i:02d}" for i in range(int(m.group(2)),int(m.group(3))+1)]
    tok=re.sub(r'\s*\(.*\)','',tok)
    return [tok] if re.match(r'^[A-Z0-9]+-\d+$',tok) else []
